import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

#!/usr/bin/env python3
"""Verify the frozen EXP-001 Proof A package without network access."""

from __future__ import annotations

import hashlib
import json
import sqlite3
import sys
from pathlib import Path


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def fail(message: str) -> None:
    print(f"FAILED: {message}", file=sys.stderr)
    raise SystemExit(1)


def main() -> None:
    root = Path(__file__).resolve().parents[1]
    manifest = json.loads((root / "manifest.json").read_text())
    for artifact in manifest["artifacts"]:
        path = root / artifact["path"]
        if not path.is_file():
            fail(f"missing {artifact['path']}")
        if path.stat().st_size != artifact["bytes"]:
            fail(f"size mismatch for {artifact['path']}")
        if sha256(path) != artifact["sha256"]:
            fail(f"SHA-256 mismatch for {artifact['path']}")
    print(f"VERIFIED: {len(manifest['artifacts'])} package artifacts match SHA-256 and byte counts")

    consensus = json.loads((root / "outputs/consensus.json").read_text())
    unit = consensus["work_units"][0]
    correlation = unit["correlations"]["rep1_vs_rep2"]
    if consensus["summary"] != {"total": 1, "passed": 1, "failed": 0, "mean_correlation": correlation}:
        fail("unexpected consensus summary")
    if not unit["passed"] or unit["outliers"] != 1 or abs(correlation - 0.8849788400337059) > 1e-15:
        fail("unexpected frozen consensus result")
    print("VERIFIED: frozen consensus reports 1/1 pass, r=0.8849788400337059, and one outlier")

    records = json.loads((root / "outputs/witness/records.json").read_text())
    counts = {kind: sum(r["epistemic_type"] == kind for r in records) for kind in ("observed", "inferred", "generated")}
    if counts != {"observed": 12, "inferred": 2, "generated": 1}:
        fail(f"unexpected Witness record counts: {counts}")
    consensus_records = [r for r in records if "consensus" in json.loads(r["labels"])]
    if len(consensus_records) != 1 or len(json.loads(consensus_records[0]["parents"])) != 12:
        fail("consensus record does not link exactly twelve premises")
    generated = [r for r in records if r["epistemic_type"] == "generated"]
    if "human_reviewed:false" not in json.loads(generated[0]["labels"]):
        fail("generated hypothesis lacks human_reviewed:false label")
    print("VERIFIED: Witness export contains 12 Observed, 2 Inferred, 1 Generated; consensus links 12 premises")

    database = root / "outputs/witness/proof-a-review.db"
    with sqlite3.connect(database) as connection:
        database_ids = {row[0] for row in connection.execute("SELECT id FROM nodes WHERE labels LIKE '%EXP-001%'")}
    if database_ids != {record["id"] for record in records}:
        fail("Witness database and JSON export identify different EXP-001 records")
    print("VERIFIED: Witness SQLite snapshot and JSON export identify the same EXP-001 records")
    print("NOT VERIFIED: source identity, molecular-docking correctness, independent execution, biological activity, efficacy, or truth")


if __name__ == "__main__":
    main()

import { useState, useEffect } from 'react'
import { invoke } from '@tauri-apps/api/core'
import { Settings, User, X, ChevronDown, ChevronUp, Pause, Play, Info, Trophy, FlaskConical, Brain, Bug, Globe, Zap, Dna } from 'lucide-react'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

import CauseSelector from './components/CauseSelector'
import ResourceControls from './components/ResourceControls'
import ThermalMonitor from './components/ThermalMonitor'
import PowerSchedule from './components/PowerSchedule'
import Dashboard from './components/Dashboard'
import ProjectStories from './components/ProjectStories'
import TeamLeaderboard from './components/TeamLeaderboard'
import SettingsPanel from './components/SettingsPanel'

// Types
interface SystemInfo {
  cpu_usage: number
  total_memory: number
  used_memory: number
  available_memory: number
  cpus: CpuInfo[]
  gpus: GpuInfo[]
  os: string
  arch: string
}

interface CpuInfo {
  name: string
  usage: number
  frequency: number
}

interface GpuInfo {
  name: string
  vendor: string
  memory_total: number
  memory_used: number
  utilization: number
  temperature: number | null
}

interface ThermalInfo {
  temperatures: TemperatureReading[]
}

interface TemperatureReading {
  label: string
  temperature: number
  max: number | null
  critical: number | null
}

interface PowerInfo {
  on_battery: boolean
  battery_percentage: number
  time_remaining: number | null
  is_charging: boolean
}

interface BoincStatus {
  running: boolean
  connected: boolean
  active_tasks: number
  gpu_tasks: number
  cpu_tasks: number
  download_speed: number
  upload_speed: number
}

interface UserSettings {
  causes: CauseAllocation[]
  cpu_limit_percent: number
  gpu_limit_percent: number
  memory_limit_gb: number
  thermal_limit_celsius: number
  thermal_resume_celsius: number
  run_on_battery: boolean
  schedule: ScheduleConfig
  network_wifi_only: boolean
  network_metered_allowed: boolean
}

interface CauseAllocation {
  id: string
  name: string
  icon: string
  percentage: number
  enabled: boolean
}

interface ScheduleConfig {
  weekday_start: string
  weekday_end: string
  weekend_all_day: boolean
  custom_hours: ScheduleEntry[]
}

interface ScheduleEntry {
  day: string
  start: string
  end: string
}

interface ContributionStats {
  total_hours: number
  validated_work_units: number
  projects_contributed: number
  papers_published: number
  current_streak: number
  total_credits: number
}

interface ProjectStory {
  project_id: string
  title: string
  description: string
  your_contribution: string
  molecules_screened: number
  hours_donated: number
  status: string
}

function cn(...inputs: (string | undefined | null | false)[]) {
  return twMerge(clsx(inputs))
}

const CAUSE_ICONS: Record<string, React.ReactNode> = {
  cancer: <Dna className="w-5 h-5" />,
  alzheimer: <Brain className="w-5 h-5" />,
  antibiotics: <Bug className="w-5 h-5" />,
  climate: <Globe className="w-5 h-5" />,
  energy: <Zap className="w-5 h-5" />,
  rare: <FlaskConical className="w-5 h-5" />,
}

function App() {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'causes' | 'resources' | 'stories' | 'teams' | 'settings'>('dashboard')
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [systemInfo, setSystemInfo] = useState<SystemInfo | null>(null)
  const [thermalInfo, setThermalInfo] = useState<ThermalInfo | null>(null)
  const [powerInfo, setPowerInfo] = useState<PowerInfo | null>(null)
  const [boincStatus, setBoincStatus] = useState<BoincStatus | null>(null)
  const [settings, setSettings] = useState<UserSettings | null>(null)
  const [contributions, setContributions] = useState<ContributionStats | null>(null)
  const [projectStories, setProjectStories] = useState<ProjectStory[]>([])
  const [loading, setLoading] = useState(true)

  // Load initial data
  useEffect(() => {
    async function loadData() {
      try {
        const [sys, therm, power, boinc, sett, contrib, stories] = await Promise.all([
          invoke<SystemInfo>('get_system_info'),
          invoke<ThermalInfo>('get_thermal_info'),
          invoke<PowerInfo>('get_power_info'),
          invoke<BoincStatus>('boinc_get_status'),
          invoke<UserSettings>('get_settings'),
          invoke<ContributionStats>('get_contributions'),
          invoke<ProjectStory[]>('get_project_stories'),
        ])
        setSystemInfo(sys)
        setThermalInfo(therm)
        setPowerInfo(power)
        setBoincStatus(boinc)
        setSettings(sett)
        setContributions(contrib)
        setProjectStories(stories)
      } catch (e) {
        console.error('Failed to load data:', e)
      } finally {
        setLoading(false)
      }
    }
    loadData()

    // Refresh system info every 5 seconds
    const interval = setInterval(() => {
      invoke<SystemInfo>('get_system_info').then(setSystemInfo).catch(console.error)
      invoke<ThermalInfo>('get_thermal_info').then(setThermalInfo).catch(console.error)
      invoke<PowerInfo>('get_power_info').then(setPowerInfo).catch(console.error)
      invoke<BoincStatus>('boinc_get_status').then(setBoincStatus).catch(console.error)
    }, 5000)

    return () => clearInterval(interval)
  }, [])

  if (loading) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="animate-pulse-soft text-primary text-xl">Humanity Grid</div>
      </div>
    )
  }

  const tabs = [
    { id: 'dashboard', label: 'Dashboard', icon: <FlaskConical className="w-5 h-5" /> },
    { id: 'causes', label: 'Causes', icon: <Dna className="w-5 h-5" /> },
    { id: 'resources', label: 'Resources', icon: <Zap className="w-5 h-5" /> },
    { id: 'stories', label: 'Impact', icon: <Trophy className="w-5 h-5" /> },
    { id: 'teams', label: 'Teams', icon: <Brain className="w-5 h-5" /> },
    { id: 'settings', label: 'Settings', icon: <Settings className="w-5 h-5" /> },
  ]

  return (
    <div className="flex h-full w-full bg-background">
      {/* Sidebar */}
      <aside className={cn(
        'fixed inset-y-0 left-0 z-50 w-64 bg-surface border-r border-border transform transition-transform duration-300 ease-in-out',
        sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
      )}>
        <div className="flex h-full flex-col">
          {/* Header */}
          <div className="flex h-16 items-center justify-between px-4 border-b border-border">
            <div className="flex items-center gap-3">
              <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
                <FlaskConical className="w-5 h-5 text-white" />
              </div>
              <span className="font-semibold text-lg">Humanity Grid</span>
            </div>
            <button
              className="lg:hidden p-2 rounded-md hover:bg-surface-elevated"
              onClick={() => setSidebarOpen(false)}
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Navigation */}
          <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => {
                  setActiveTab(tab.id as typeof activeTab)
                  setSidebarOpen(false)
                }}
                className={cn(
                  'flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors',
                  activeTab === tab.id
                    ? 'bg-primary/20 text-primary border border-primary/30'
                    : 'text-text-muted hover:bg-surface-elevated hover:text-text'
                )}
              >
                {tab.icon}
                {tab.label}
              </button>
            ))}

            {/* BOINC Status Indicator */}
            <div className="mt-4 rounded-lg border border-border bg-surface-elevated p-3">
              <div className="flex items-center justify-between text-xs text-text-muted mb-2">
                <span>BOINC Status</span>
                <span className={cn(
                  'flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium',
                  boincStatus?.running ? 'bg-success/20 text-success' : 'bg-error/20 text-error'
                )}>
                  <span className={cn('h-1.5 w-1.5 rounded-full', boincStatus?.running ? 'bg-success' : 'bg-error')} />
                  {boincStatus?.running ? 'Running' : 'Stopped'}
                </span>
              </div>
              <div className="grid grid-cols-2 gap-2 text-center">
                <div>
                  <div className="text-lg font-bold">{boincStatus?.active_tasks ?? 0}</div>
                  <div className="text-[11px] text-text-subtle">Active</div>
                </div>
                <div>
                  <div className="text-lg font-bold">{boincStatus?.gpu_tasks ?? 0}</div>
                  <div className="text-[11px] text-text-subtle">GPU</div>
                </div>
              </div>
            </div>
          </nav>

          {/* Footer */}
          <div className="border-t border-border p-4">
            <div className="flex items-center gap-3 text-sm text-text-muted">
              <span className="text-xs">v0.1.0</span>
              <span className="flex-1" />
              <a href="https://github.com/seanebones-lang/Humanity-Grid" target="_blank" rel="noopener noreferrer" className="hover:text-primary">
                GitHub
              </a>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Main content */}
      <main className="flex-1 lg:ml-64 flex flex-col min-w-0">
        {/* Top bar */}
        <header className="flex h-14 items-center justify-between px-4 border-b border-border bg-background/80 backdrop-blur-sm sticky top-0 z-10">
          <button
            className="lg:hidden p-2 rounded-md hover:bg-surface-elevated"
            onClick={() => setSidebarOpen(true)}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>

          <div className="flex-1 lg:flex-none" />

          <div className="flex items-center gap-3">
            {/* System quick stats */}
            {systemInfo && (
              <div className="hidden sm:flex items-center gap-4 text-xs text-text-muted">
                <div className="flex items-center gap-1">
                  <span className={cn('h-2 w-2 rounded-full', systemInfo.cpu_usage > 80 ? 'bg-error' : systemInfo.cpu_usage > 50 ? 'bg-warning' : 'bg-success')} />
                  <span>{systemInfo.cpu_usage.toFixed(0)}% CPU</span>
                </div>
                <div className="flex items-center gap-1">
                  <span className={cn('h-2 w-2 rounded-full', 
                    (systemInfo.used_memory / systemInfo.total_memory) > 0.8 ? 'bg-error' : 
                    (systemInfo.used_memory / systemInfo.total_memory) > 0.5 ? 'bg-warning' : 'bg-success')} />
                  <span>{(systemInfo.used_memory / systemInfo.total_memory * 100).toFixed(0)}% RAM</span>
                </div>
              </div>
            )}

            <div className="flex items-center gap-2">
              <button className="p-2 rounded-lg hover:bg-surface-elevated" title="Settings">
                <Settings className="w-5 h-5" />
              </button>
              <button className="p-2 rounded-lg hover:bg-surface-elevated" title="Profile">
                <User className="w-5 h-5" />
              </button>
            </div>
          </div>
        </header>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-6">
          {activeTab === 'dashboard' && (
            <Dashboard
              systemInfo={systemInfo}
              thermalInfo={thermalInfo}
              powerInfo={powerInfo}
              boincStatus={boincStatus}
              contributions={contributions}
            />
          )}

          {activeTab === 'causes' && (
            <CauseSelector
              settings={settings}
              onUpdate={setSettings}
            />
          )}

          {activeTab === 'resources' && (
            <ResourceControls
              systemInfo={systemInfo}
              thermalInfo={thermalInfo}
              powerInfo={powerInfo}
              settings={settings}
              onUpdate={setSettings}
            />
          )}

          {activeTab === 'stories' && (
            <ProjectStories
              stories={projectStories}
              contributions={contributions}
            />
          )}

          {activeTab === 'teams' && (
            <TeamLeaderboard />
          )}

          {activeTab === 'settings' && (
            <SettingsPanel
              settings={settings}
              onUpdate={setSettings}
            />
          )}
        </div>
      </main>
    </div>
  )
}

export default App

-- Initial schema for Humanity Grid Volunteer App
CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE contributions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT NOT NULL,
    work_unit_id TEXT NOT NULL,
    hours REAL NOT NULL,
    validated BOOLEAN DEFAULT FALSE,
    credits INTEGER DEFAULT 0,
    completed_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE project_stories (
    project_id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    description TEXT,
    your_contribution TEXT,
    molecules_screened INTEGER DEFAULT 0,
    hours_donated REAL DEFAULT 0,
    status TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE teams (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE team_members (
    team_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    joined_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (team_id, user_id)
);

CREATE INDEX idx_contributions_project ON contributions(project_id);
CREATE INDEX idx_contributions_completed_at ON contributions(completed_at);

import { useState } from 'react'
import { Slider, Checkbox, Label } from '@/components/ui'
import { invoke } from '@tauri-apps/api/core'
import { Dna, Brain, Bug, Globe, Zap, FlaskConical } from 'lucide-react'
import { UserSettings, CauseAllocation } from '@/types'

interface CauseSelectorProps {
  settings: UserSettings | null
  onUpdate: (settings: UserSettings) => void
}

const CAUSES: Omit<CauseAllocation, 'percentage' | 'enabled'>[] = [
  { id: 'cancer', name: 'Cancer Research', icon: <Dna className="w-5 h-5" /> },
  { id: 'alzheimer', name: "Alzheimer's Research", icon: <Brain className="w-5 h-5" /> },
  { id: 'antibiotics', name: 'Antibiotic Discovery', icon: <Bug className="w-5 h-5" /> },
  { id: 'climate', name: 'Climate Modeling', icon: <Globe className="w-5 h-5" /> },
  { id: 'energy', name: 'Clean Energy Materials', icon: <Zap className="w-5 h-5" /> },
  { id: 'rare', name: 'Rare Diseases', icon: <FlaskConical className="w-5 h-5" /> },
]

export default function CauseSelector({ settings, onUpdate }: CauseSelectorProps) {
  const [causes, setCauses] = useState<CauseAllocation[]>(settings?.causes || CAUSES.map(c => ({ ...c, percentage: 0, enabled: false })))

  const totalPercentage = causes.reduce((sum, c) => sum + (c.enabled ? c.percentage : 0), 0)

  const handlePercentageChange = (id: string, percentage: number) => {
    const newCauses = causes.map(c => c.id === id ? { ...c, percentage } : c)
    setCauses(newCauses)
    if (settings) onUpdate({ ...settings, causes: newCauses })
  }

  const handleEnabledChange = (id: string, enabled: boolean) => {
    const newCauses = causes.map(c => c.id === id ? { ...c, enabled } : c)
    setCauses(newCauses)
    if (settings) onUpdate({ ...settings, causes: newCauses })
  }

  const normalizePercentages = () => {
    const enabledCauses = causes.filter(c => c.enabled)
    if (enabledCauses.length === 0) return
    const perCause = Math.floor(100 / enabledCauses.length)
    const remainder = 100 % enabledCauses.length
    const newCauses = causes.map((c, i) => {
      if (!c.enabled) return { ...c, percentage: 0 }
      return { ...c, percentage: perCause + (i < remainder ? 1 : 0) }
    })
    setCauses(newCauses)
    if (settings) onUpdate({ ...settings, causes: newCauses })
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div>
        <h1 className="text-2xl font-bold mb-2">What do you want your computer working on tonight?</h1>
        <p className="text-text-muted">Choose the research areas you want to support. Drag to allocate your compute percentage.</p>
      </div>

      <div className="glass rounded-xl p-6 space-y-4">
        {CAUSES.map((cause, index) => {
          const causeData = causes.find(c => c.id === cause.id) || { percentage: 0, enabled: false }
          return (
            <div key={cause.id} className="flex items-center gap-4 p-4 rounded-lg bg-surface/50 border border-border/50">
              <div className="flex items-center justify-center w-10 h-10 rounded-lg bg-primary/10 text-primary">
                {cause.icon}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <h3 className="font-medium truncate">{cause.name}</h3>
                  <Checkbox
                    checked={causeData.enabled}
                    onCheckedChange={checked => handleEnabledChange(cause.id, checked)}
                    className="data-[state=checked]:bg-primary data-[state=checked]:border-primary"
                  />
                </div>
                {causeData.enabled && (
                  <div className="mt-2 space-y-1">
                    <div className="flex justify-between text-sm">
                      <span className="text-text-muted">Compute allocation</span>
                      <span className="font-mono font-medium">{causeData.percentage}%</span>
                    </div>
                    <Slider
                      value={[causeData.percentage]}
                      onValueChange={([value]) => handlePercentageChange(cause.id, value)}
                      max={100}
                      step={5}
                      disabled={!causeData.enabled}
                      className="h-2"
                    />
                  </div>
                )}
              </div>
            </div>
          )
        })}
      </div>

      <div className="glass rounded-xl p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-semibold">Total Allocation</h3>
          <span className={totalPercentage === 100 ? 'text-success' : totalPercentage > 100 ? 'text-error' : 'text-warning'} className="font-mono text-lg">
            {totalPercentage}%
          </span>
        </div>
        <div className="h-3 bg-surface rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-primary to-primary-light rounded-full transition-all duration-300"
            style={{ width: `${Math.min(totalPercentage, 100)}%` }}
          />
        </div>
        {totalPercentage !== 100 && (
          <p className="mt-2 text-sm text-text-muted">
            {totalPercentage < 100 ? `${100 - totalPercentage}% unallocated` : `${totalPercentage - 100}% overallocated`}
          </p>
        )}
        {totalPercentage > 0 && totalPercentage !== 100 && (
          <button
            onClick={normalizePercentages}
            className="mt-4 w-full sm:w-auto px-4 py-2 rounded-lg bg-primary/10 text-primary hover:bg-primary/20 text-sm font-medium transition-colors"
          >
            Auto-balance ({Math.floor(100 / causes.filter(c => c.enabled).length)}% each)
          </button>
        )}
      </div>

      <div className="glass rounded-xl p-6 border-border/50">
        <h3 className="font-semibold mb-3">How it works</h3>
        <ul className="space-y-2 text-sm text-text-muted">
          <li className="flex items-start gap-2"><span className="text-primary mt-0.5">●</span> Your computer downloads small work units from our BOINC server</li>
          <li className="flex items-start gap-2"><span className="text-primary mt-0.5">●</span> Each unit tests ~1,000 molecules against a cancer protein target</li>
          <li className="flex items-start gap-2"><span className="text-primary mt-0.5">●</span> Results are validated by comparing with other volunteers' computers</li>
          <li className="flex items-start gap-2"><span className="text-primary mt-0.5">●</span> Validated results earn credits and contribute to published research</li>
          <li className="flex items-start gap-2"><span className="text-primary mt-0.5">●</span> All data and findings are publicly available — no patents, no paywalls</li>
        </ul>
      </div>
    </div>
  )
}

import * as React from 'react'
import { cn } from '@/lib/utils'

export interface SliderProps extends React.ComponentPropsWithoutRef<typeof React.ForwardRefExoticComponent<React.SliderHTMLAttributes<HTMLInputElement>>> {
  value: number[]
  onValueChange: (value: number[]) => void
  max?: number
  min?: number
  step?: number
  disabled?: boolean
  className?: string
}

const Slider = React.forwardRef<HTMLInputElement, SliderProps>(
  ({ className, value, onValueChange, max = 100, min = 0, step = 1, disabled, ...props }, ref) => {
    return (
      <div className="relative w-full" data-disabled={disabled}>
        <input
          type="range"
          ref={ref}
          className={cn(
            'appearance-none w-full h-2 bg-surface rounded-full cursor-pointer',
            'focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background',
            'disabled:opacity-50 disabled:cursor-not-allowed',
            className
          )}
          min={min}
          max={max}
          step={step}
          value={value[0]}
          onChange={(e) => onValueChange([Number(e.target.value)])}
