/**
 * Security helpers for middleware (sync, no async cookies).
 * Full CSRF utilities live in lib/security/csrf.ts.
 */

function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) {
    result |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return result === 0;
}

/** Generate a secure random token (sync for middleware). */
export function generateCSRF(): string {
  const crypto = require('crypto');
  return crypto.randomBytes(32).toString('hex');
}

/** Validate CSRF: header token must match cookie token (sync). */
export function validateCSRF(headerToken: string, cookieToken: string): boolean {
  if (!headerToken || !cookieToken) return false;
  return constantTimeEquals(headerToken, cookieToken);
}

import { NextResponse } from 'next/server'

export type ApiErrorBody = {
  error: string
  code?: string
  requestId?: string
  hint?: string
  /** Extra context for operators (e.g. upstream message); avoid displaying raw secrets. */
  details?: string
}

/**
 * JSON error responses with optional stable `code` for clients and `X-Request-Id` when provided.
 */
export function jsonApiError(
  status: number,
  message: string,
  opts?: { code?: string; requestId?: string; hint?: string; details?: string }
): NextResponse<ApiErrorBody> {
  const body: ApiErrorBody = { error: message }
  if (opts?.code) body.code = opts.code
  if (opts?.requestId) body.requestId = opts.requestId
  if (opts?.hint) body.hint = opts.hint
  if (opts?.details) body.details = opts.details
  const headers = new Headers()
  if (opts?.requestId) headers.set('X-Request-Id', opts.requestId)
  return NextResponse.json(body, { status, headers })
}

