/**
 * In-memory TTS response cache for repeat lines (solo-creator workflow).
 * Cache key = hash of text + voice_id + params. Max 200 entries, LRU eviction.
 * March 2026
 */

import { createHash } from 'node:crypto'

const MAX_ENTRIES = 200

interface CacheEntry {
  buffer: ArrayBuffer
  contentType: string
  createdAt: number
}

const cache = new Map<string, CacheEntry>()
const keyOrder: string[] = []

function hash(payload: string): string {
  // Collision-resistant hash so distinct requests do not share audio.
  return createHash('sha256').update(payload).digest('hex')
}

export function buildTtsCacheKey(params: {
  text: string
  voice_id: string
  language: string
  speed: number
  pitch: number
  volume: number
  reverb: number
  echo: number
  noise_reduction: boolean
  special_effect: string
  /** Clone tuning segment so preset / sampling changes bust cache correctly. */
  clone_tune?: string
  /** Emotion preset (server merges into prosody; included for cache correctness). */
  emotion?: string
}): string {
  const payload = [
    params.text.trim(),
    params.voice_id,
    params.language,
    params.speed,
    params.pitch,
    params.volume,
    params.reverb,
    params.echo,
    params.noise_reduction ? '1' : '0',
    params.special_effect,
    params.clone_tune ?? '',
    params.emotion ?? 'neutral',
  ].join('\0')
  return hash(payload)
}

export function getCached(key: string): { buffer: ArrayBuffer; contentType: string } | null {
  const entry = cache.get(key)
  if (!entry) return null
  // Move to end (most recently used)
  const idx = keyOrder.indexOf(key)
  if (idx !== -1) {
    keyOrder.splice(idx, 1)
    keyOrder.push(key)
  }
  return { buffer: entry.buffer, contentType: entry.contentType }
}

export function setCached(key: string, buffer: ArrayBuffer, contentType: string): void {
  while (cache.size >= MAX_ENTRIES && keyOrder.length > 0) {
    const oldest = keyOrder.shift()!
    cache.delete(oldest)
  }
  cache.set(key, { buffer, contentType, createdAt: Date.now() })
  keyOrder.push(key)
}

/**
 * CORS Configuration Utility
 * Provides secure CORS headers for Next.js API routes
 */

/**
 * Get allowed origins from environment variable
 * Falls back to single origin if not configured
 */
export function getAllowedOrigins(): string[] {
  const allowedOrigins = process.env.ALLOWED_ORIGINS

  if (!allowedOrigins) {
    // Default to same origin only (most secure)
    return []
  }

  // Support comma-separated list of origins
  return allowedOrigins
    .split(',')
    .map(origin => origin.trim())
    .filter(origin => origin.length > 0)
}

/**
 * Check if origin is allowed
 */
export function isOriginAllowed(origin: string | null, allowedOrigins: string[]): boolean {
  if (!origin) {
    // Same-origin requests (no Origin header)
    return true
  }

  if (allowedOrigins.length === 0) {
    // No explicit origins configured - allow same origin only
    return false
  }

  return allowedOrigins.includes(origin)
}

/**
 * Get CORS headers for response
 * When origin is null (same-origin), we omit Allow-Origin to avoid sending '*'
 * with credentials (invalid per CORS spec). Same-origin requests don't need CORS headers.
 */
export function getCorsHeaders(origin: string | null): Record<string, string> {
  const allowedOrigins = getAllowedOrigins()
  const headers: Record<string, string> = {}

  if (isOriginAllowed(origin, allowedOrigins)) {
    // Only set Allow-Origin when we have an origin; never use '*' with credentials
    if (origin) {
      headers['Access-Control-Allow-Origin'] = origin
    }
    headers['Access-Control-Allow-Methods'] = 'GET, POST, PUT, DELETE, OPTIONS'
    headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization'
    headers['Access-Control-Allow-Credentials'] = 'true'
    headers['Access-Control-Max-Age'] = '86400' // 24 hours
  }

  return headers
}

/**
 * Handle CORS preflight request
 */
export function handleCorsPreflight(origin: string | null) {
  const allowedOrigins = getAllowedOrigins()

  if (!isOriginAllowed(origin, allowedOrigins)) {
    return new Response(null, { status: 403 })
  }

  const headers = getCorsHeaders(origin)
  return new Response(null, { 
    status: 204,
    headers 
  })
}

/**
 * XTTS Sidecar Client
 * Communicates with Python FastAPI service for voice cloning
 */

const XTTS_SIDECAR_URL = process.env.XTTS_SIDECAR_URL || 'http://localhost:8081'

export interface CloneVoiceRequest {
  name: string
  description?: string
  files: File[]
}

export interface CloneVoiceResponse {
  success: boolean
  voice_id: string
  speaker_embedding: string
  name: string
  description?: string
  message: string
}

export interface TTSWithCloneRequest {
  text: string
  speaker_embedding: string
  language?: string
}

export class XTTSClient {
  private baseUrl: string

  constructor(baseUrl: string = XTTS_SIDECAR_URL) {
    this.baseUrl = baseUrl
  }

  /**
   * Check if XTTS service is available
   */
  async healthCheck(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/health`)
      const data = await response.json()
      return data.status === 'healthy'
    } catch {
      return false
    }
  }

  /**
   * Clone a voice from reference audio files
   */
  async cloneVoice(request: CloneVoiceRequest): Promise<CloneVoiceResponse> {
    const formData = new FormData()
    formData.append('name', request.name)
    if (request.description) {
      formData.append('description', request.description)
    }

    request.files.forEach((file) => {
      formData.append('files', file)
    })

    const response = await fetch(`${this.baseUrl}/clone`, {
      method: 'POST',
      body: formData,
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.detail || 'Voice cloning failed')
    }

    return response.json()
  }

  /**
   * Generate speech using cloned voice
   */
  async generateSpeech(request: TTSWithCloneRequest): Promise<Blob> {
    const response = await fetch(`${this.baseUrl}/tts`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        text: request.text,
        speaker_embedding: request.speaker_embedding,
        language: request.language || 'en',
      }),
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.detail || 'TTS generation failed')
    }

    return response.blob()
  }
}

/**
 * Web Vitals Performance Monitoring
 * Tracks Core Web Vitals and sends to analytics
 */

export interface Metric {
  id: string
  name: string
  value: number
  rating: 'good' | 'needs-improvement' | 'poor'
  delta: number
  entries: PerformanceEntry[]
}

type ReportCallback = (metric: Metric) => void

// Web Vitals thresholds
const THRESHOLDS = {
  LCP: { good: 2500, poor: 4000 },
  FID: { good: 100, poor: 300 },
  CLS: { good: 0.1, poor: 0.25 },
  FCP: { good: 1800, poor: 3000 },
  TTFB: { good: 800, poor: 1800 },
}

function getRating(name: string, value: number): 'good' | 'needs-improvement' | 'poor' {
  const threshold = THRESHOLDS[name as keyof typeof THRESHOLDS]
  if (!threshold) return 'good'

  if (value <= threshold.good) return 'good'
  if (value <= threshold.poor) return 'needs-improvement'
  return 'poor'
}

function sendToAnalytics(metric: Metric) {
  // Send to your analytics service
  // Example: Google Analytics, Sentry, custom endpoint

  if (typeof window !== 'undefined' && (window as any).gtag) {
    ;(window as any).gtag('event', metric.name, {
      value: Math.round(metric.value),
      metric_id: metric.id,
      metric_value: metric.value,
      metric_delta: metric.delta,
      metric_rating: metric.rating,
    })
  }

  // Log to console in development
  if (process.env.NODE_ENV === 'development') {
    console.log(`📊 ${metric.name}:`, {
      value: metric.value.toFixed(2),
      rating: metric.rating,
      delta: metric.delta.toFixed(2),
    })
  }

  // Send to custom endpoint if configured
  if (process.env.NEXT_PUBLIC_ANALYTICS_ENDPOINT) {
    fetch(process.env.NEXT_PUBLIC_ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(metric),
      keepalive: true,
    }).catch(() => {
      // Silently fail
    })
  }
}

export function reportWebVitals(onPerfEntry?: ReportCallback) {
  if (typeof window === 'undefined') return

  import('web-vitals').then(({ onCLS, onFID, onFCP, onLCP, onTTFB, onINP }) => {
    const report = (metric: Metric) => {
      const ratedMetric = {
        ...metric,
        rating: getRating(metric.name, metric.value),
      }

      sendToAnalytics(ratedMetric)
      onPerfEntry?.(ratedMetric)
    }

    onCLS(report)
    onFID(report)
    onFCP(report)
    onLCP(report)
    onTTFB(report)
    onINP(report)
  }).catch(() => {
    // web-vitals not available
  })
}

/**
 * CSRF Protection Utility
 * Implements double-submit cookie pattern for CSRF protection
 */

import { cookies } from 'next/headers'

const CSRF_TOKEN_COOKIE = 'csrf-token'
const CSRF_TOKEN_HEADER = 'X-CSRF-Token'

/**
 * Generate a secure random CSRF token
 */
export function generateCSRFToken(): string {
  // Use crypto.randomBytes for secure random generation
  const array = new Uint8Array(32)
  if (typeof window !== 'undefined' && window.crypto) {
    window.crypto.getRandomValues(array)
  } else {
    // Node.js fallback
    const crypto = require('crypto')
    crypto.randomFillSync(array)
  }

  return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('')
}

/**
 * Set CSRF token in cookie (for double-submit pattern)
 */
export async function setCSRFToken(): Promise<string> {
  const token = generateCSRFToken()
  const cookieStore = await cookies()

  cookieStore.set(CSRF_TOKEN_COOKIE, token, {
    httpOnly: false, // Must be readable by JavaScript for double-submit
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
    maxAge: 60 * 60 * 24, // 24 hours
  })

  return token
}

/**
 * Get CSRF token from cookie
 */
export async function getCSRFToken(): Promise<string | null> {
  const cookieStore = await cookies()
  return cookieStore.get(CSRF_TOKEN_COOKIE)?.value || null
}

/**
 * Validate CSRF token from request
 * Implements double-submit cookie pattern:
 * 1. Token in cookie (set by server)
 * 2. Token in header/body (sent by client)
 * Both must match
 */
export async function validateCSRFToken(
  requestToken: string | null
): Promise<boolean> {
  if (!requestToken) {
    return false
  }

  const cookieToken = await getCSRFToken()

  if (!cookieToken) {
    return false
  }

  // Constant-time comparison to prevent timing attacks
  return constantTimeEquals(cookieToken, requestToken)
}

/**
 * Constant-time string comparison to prevent timing attacks
 */
function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) {
    return false
  }

  let result = 0
  for (let i = 0; i < a.length; i++) {
    result |= a.charCodeAt(i) ^ b.charCodeAt(i)
  }

  return result === 0
}

/**
 * Extract CSRF token from request headers or body
 */
export function extractCSRFTokenFromRequest(
  headers: Headers,
  body?: Record<string, unknown>
): string | null {
  // Check header first
  const headerToken = headers.get(CSRF_TOKEN_HEADER)
  if (headerToken) {
    return headerToken
  }

  // Check body
  if (body && typeof body === 'object' && CSRF_TOKEN_HEADER in body) {
    const bodyToken = body[CSRF_TOKEN_HEADER]
    return typeof bodyToken === 'string' ? bodyToken : null
  }

  return null
}

import { Ratelimit } from "@upstash/ratelimit"
import { Redis } from "@upstash/redis"

// Check if Redis is configured
const hasRedis = process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN

const redis = hasRedis ? new Redis({
  url: process.env.UPSTASH_REDIS_REST_URL!,
  token: process.env.UPSTASH_REDIS_REST_TOKEN!,
}) : null

// In-memory rate limiter for fallback (when Redis not configured)
// Uses Map to store request counts per identifier
const inMemoryStore = new Map<string, { count: number; resetTime: number }>()

// Cleanup old entries periodically
setInterval(() => {
  const now = Date.now()
  for (const [key, value] of inMemoryStore.entries()) {
    if (value.resetTime < now) {
      inMemoryStore.delete(key)
    }
  }
}, 60000) // Cleanup every minute

// Fallback rate limiter with in-memory storage
const createFallbackLimiter = (windowMs: number, maxRequests: number) => ({
  limit: async (identifier: string) => {
    const now = Date.now()
    const resetTime = now + windowMs

    // Get or create entry
    let entry = inMemoryStore.get(identifier)

    if (!entry || entry.resetTime < now) {
      // New window or expired entry
      entry = { count: 1, resetTime }
      inMemoryStore.set(identifier, entry)
      return {
        success: true,
        limit: maxRequests,
        remaining: maxRequests - 1,
        reset: resetTime,
      }
    }

    // Increment count
    entry.count++

    if (entry.count > maxRequests) {
      return {
        success: false,
        limit: maxRequests,
        remaining: 0,
        reset: entry.resetTime,
      }
    }

    inMemoryStore.set(identifier, entry)

    return {
      success: true,
      limit: maxRequests,
      remaining: maxRequests - entry.count,
      reset: entry.resetTime,
    }
  },
})

// Single-user mode: no effective rate limits (high ceilings so they never trigger)
const UNLIMITED_WINDOW_MS = 15 * 60 * 1000
const UNLIMITED_REQUESTS = 100000

// Create rate limiter: effectively unlimited for single user
export const rateLimiter = hasRedis && redis ? new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(UNLIMITED_REQUESTS, "15 m"),
  analytics: true,
  prefix: "@upstash/ratelimit",
}) : createFallbackLimiter(UNLIMITED_WINDOW_MS, UNLIMITED_REQUESTS)

// TTS: effectively unlimited for single user
export const ttsRateLimiter = hasRedis && redis ? new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(UNLIMITED_REQUESTS, "1 h"),
  analytics: true,
  prefix: "@upstash/ratelimit/tts",
}) : createFallbackLimiter(60 * 60 * 1000, UNLIMITED_REQUESTS)

// Cloning: effectively unlimited for single user
export const cloneRateLimiter = hasRedis && redis ? new Ratelimit({
  redis,
  limiter: Ratelimit.slidingWindow(UNLIMITED_REQUESTS, "1 d"),
  analytics: true,
  prefix: "@upstash/ratelimit/clone",
}) : createFallbackLimiter(24 * 60 * 60 * 1000, UNLIMITED_REQUESTS)

/**
 * Edge TTS fallback when XTTS sidecar is unreachable (e.g. Railway single-service).
 * Uses Microsoft Edge TTS so default (standard) voices still work.
 */

import { EdgeTTS } from 'edge-tts-universal'

// Map our voice_id -> Edge Neural voice name (Microsoft format)
const EDGE_VOICE_MAP: Record<string, string> = {
  default_english: 'en-US-GuyNeural',
  male_us_aria: 'en-US-DavisNeural',
  male_us_davis: 'en-US-DavisNeural',
  female_english: 'en-US-JennyNeural',
  female_us_aria: 'en-US-AriaNeural',
  female_us_amber: 'en-US-AmberNeural',
  male_british: 'en-GB-RyanNeural',
  male_british_libby: 'en-GB-LibbyNeural',
  female_british: 'en-GB-SoniaNeural',
  female_british_libby: 'en-GB-LibbyNeural',
  default_spanish: 'es-ES-AlvaroNeural',
  spanish_female: 'es-ES-ElviraNeural',
  default_french: 'fr-FR-HenriNeural',
  french_female: 'fr-FR-DeniseNeural',
  default_german: 'de-DE-ConradNeural',
  german_female: 'de-DE-KatjaNeural',
  default_portuguese: 'pt-BR-AntonioNeural',
  portuguese_female: 'pt-BR-FranciscaNeural',
  italian_male: 'it-IT-DiegoNeural',
  italian_female: 'it-IT-ElsaNeural',
  japanese_male: 'ja-JP-KeitaNeural',
  japanese_female: 'ja-JP-NanamiNeural',
  chinese_male: 'zh-CN-YunyangNeural',
  chinese_female: 'zh-CN-XiaoxiaoNeural',
  korean_male: 'ko-KR-InJoonNeural',
  korean_female: 'ko-KR-SunHiNeural',
}

export function isDefaultVoiceId(voiceId: string): boolean {
  return voiceId in EDGE_VOICE_MAP
}

function getEdgeVoice(voiceId: string): string {
  return EDGE_VOICE_MAP[voiceId] ?? 'en-US-GuyNeural'
}

export interface EdgeTtsOptions {
  speed?: number
  pitch?: number
  volume?: number
}

/**
 * Synthesize speech using Edge TTS. Returns MP3 buffer.
 */
export async function synthesizeEdgeTts(
  text: string,
  voiceId: string,
  options: EdgeTtsOptions = {}
): Promise<Buffer> {
  const edgeVoice = getEdgeVoice(voiceId)
  const { speed = 1, pitch = 0, volume = 1 } = options
  const ratePercent = Math.round((speed - 1) * 100)
  const rateStr = ratePercent >= 0 ? `+${ratePercent}%` : `${ratePercent}%`
  const pitchHz = Math.round(pitch * 10)
  const pitchStr = pitchHz >= 0 ? `+${pitchHz}Hz` : `${pitchHz}Hz`

  // edge-tts-universal requires /^[+-]\d+%$/ (e.g. +94%, not 94%)
  const volumeStr =
    volume !== 1 ? `+${Math.round(volume * 100)}%` : undefined
  const tts = new EdgeTTS(text, edgeVoice, {
    rate: rateStr,
    pitch: pitchStr,
    volume: volumeStr,
  })
  const result = await tts.synthesize()

  // Handle different possible return types from edge-tts-universal
  let buffer: Buffer
  if (result.audio instanceof Buffer) {
    buffer = result.audio
  } else if (result.audio instanceof ArrayBuffer) {
    buffer = Buffer.from(result.audio)
  } else if (result.audio && typeof result.audio.arrayBuffer === 'function') {
    const arrayBuffer = await result.audio.arrayBuffer()
    buffer = Buffer.from(arrayBuffer)
  } else if (result.audio && typeof result.audio === 'object' && 'buffer' in result.audio) {
    // Handle Uint8Array or typed array
    buffer = Buffer.from((result.audio as { buffer: ArrayBuffer }).buffer)
  } else {
    throw new Error(`Unexpected audio type from edge-tts-universal: ${typeof result.audio}`)
  }

  if (buffer.length === 0) {
    throw new Error('Edge TTS returned empty audio buffer')
  }

  console.log(`✅ Edge TTS fallback: ${buffer.length} bytes, voice=${edgeVoice}`)
  return buffer
}

import { and, eq } from "drizzle-orm"
import type { WebhookEvent } from "@clerk/backend"
