  }
  if (priceId === tierPro) {
    return {
      ...base,
      "voice.clone": true,
      "api.access": true,
      "analytics.dashboard": true,
      "collab.max_members": 25,
    }
  }
  if (priceId === tierTeam) {
    return {
      ...base,
      "voice.clone": true,
      "api.access": true,
      "analytics.dashboard": true,
      "collab.max_members": 100,
