/**
 * Responsive Card Grid
 * Grid of cards with responsive columns
 */
interface CardGridProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Number of columns at different breakpoints
   */
  cols?: {
    sm?: number
    md?: number
    lg?: number
    xl?: number
  }
  /**
   * Gap between cards
   */
  gap?: 'tight' | 'compact' | 'default' | 'loose'
}

const cardGridColsMap: Record<number, string> = {
  1: 'grid-cols-1',
  2: 'grid-cols-2',
  3: 'grid-cols-3',
  4: 'grid-cols-4',
  5: 'grid-cols-5',
  6: 'grid-cols-6',
  12: 'grid-cols-12',
}

const cardGridColsMapMd: Record<number, string> = {
  1: 'md:grid-cols-1',
  2: 'md:grid-cols-2',
  3: 'md:grid-cols-3',
  4: 'md:grid-cols-4',
  5: 'md:grid-cols-5',
  6: 'md:grid-cols-6',
  12: 'md:grid-cols-12',
}

const cardGridColsMapLg: Record<number, string> = {
  1: 'lg:grid-cols-1',
  2: 'lg:grid-cols-2',
  3: 'lg:grid-cols-3',
  4: 'lg:grid-cols-4',
  5: 'lg:grid-cols-5',
  6: 'lg:grid-cols-6',
  12: 'lg:grid-cols-12',
}

const cardGridColsMapXl: Record<number, string> = {
  1: 'xl:grid-cols-1',
  2: 'xl:grid-cols-2',
  3: 'xl:grid-cols-3',
  4: 'xl:grid-cols-4',
  5: 'xl:grid-cols-5',
  6: 'xl:grid-cols-6',
  12: 'xl:grid-cols-12',
}

export const CardGrid = React.memo(function CardGrid({
  children,
  className,
  cols = { sm: 1, md: 2, lg: 3 },
  gap = 'default',
  ...props
}: CardGridProps) {
  const gridCols = [
    cols.sm && cardGridColsMap[cols.sm],
    cols.md && cardGridColsMapMd[cols.md],
    cols.lg && cardGridColsMapLg[cols.lg],
    cols.xl && cardGridColsMapXl[cols.xl],
  ].filter(Boolean).join(' ')

  const gapClasses = {
    tight: 'gap-2 sm:gap-3',
    compact: 'gap-3 sm:gap-4',
    default: 'gap-4 sm:gap-6',
    loose: 'gap-6 sm:gap-8',
  }

  return (
    <div
      className={cn(
        'grid',
        gridCols || 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
        gapClasses[gap],
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
})

import { verifyToken } from "@clerk/backend"

/**
 * Verify a Clerk-issued JWT (Bearer) for API routes.
 * Returns Clerk user id (`sub`) if valid.
 */
export async function verifyBearerToken(token: string): Promise<{ userId: string } | null> {
  const secretKey = process.env.CLERK_SECRET_KEY
  if (!secretKey || !token) return null
  try {
    const payload = await verifyToken(token, { secretKey })
    const sub = typeof payload.sub === "string" ? payload.sub : null
    if (!sub) return null
    return { userId: sub }
  } catch {
    return null
  }
}

