describe('applyEmotionProsody', () => {
  const base = {
    speed: 1,
    pitch: 0,
    volume: 1,
    reverb: 0,
    echo: 0,
    noise_reduction: false,
    special_effect: 'none',
  }

  it('leaves neutral unchanged', () => {
