/**
 * Centralized Configuration & Service Discovery
 * Handles Railway service URLs, environment detection, and service health
 * Date: March 2026
 */

export interface ServiceConfig {
  url: string
  healthEndpoint: string
  timeout: number
  retries: number
}

export interface AppConfig {
  environment: 'development' | 'production' | 'staging'
  isRailway: boolean
  xttsConfigured: boolean
  services: {
    xtts: ServiceConfig
    ttsV2: ServiceConfig
    rag: ServiceConfig
  }
  railway: {
    projectId: string
    environmentId: string
    token: string
  }
}

// Detect environment
const isRailway = !!process.env.RAILWAY_ENVIRONMENT || !!process.env.RAILWAY_PROJECT_ID
const isProduction = process.env.NODE_ENV === 'production'

// Railway service discovery. Support XTTS_URL (current) and XTTS_SIDECAR_URL (legacy).
const resolveServiceUrl = (serviceName: string, defaultPort: number, envVar?: string, legacyEnvVar?: string): string => {
  if (envVar && process.env[envVar]) return process.env[envVar]!
  if (legacyEnvVar && process.env[legacyEnvVar]) return process.env[legacyEnvVar]!
  if (isRailway) return `http://${serviceName}:${defaultPort}`
  return `http://localhost:${defaultPort}`
}

// Service configurations
export const config: AppConfig = {
  environment: isProduction ? 'production' : 'development',
  isRailway,
  xttsConfigured: !!(process.env.XTTS_URL || process.env.XTTS_SIDECAR_URL),
  services: {
    xtts: {
      url: resolveServiceUrl('xtts-service', 8081, 'XTTS_URL', 'XTTS_SIDECAR_URL'),
      healthEndpoint: '/health',
      timeout: 30000, // 30s for TTS generation
      retries: 2,
    },
    ttsV2: {
      url: resolveServiceUrl('tts-v2-service', 8082, 'TTS_V2_URL'),
      healthEndpoint: '/health',
      timeout: 45000, // 45s for advanced TTS
      retries: 2,
    },
    rag: {
      url: resolveServiceUrl('rag-service', 8001, 'RAG_API_URL'),
      healthEndpoint: '/health',
      timeout: 10000, // 10s for RAG queries
      retries: 1,
    },
  },
  railway: {
    projectId: process.env.RAILWAY_PROJECT_ID || '',
    environmentId: process.env.RAILWAY_ENVIRONMENT_ID || '',
    token: process.env.RAILWAY_TOKEN || '',
  },
}

// Service health check; pass timeoutMs for fast health endpoint (e.g. 5000)
export async function checkServiceHealth(
  service: ServiceConfig,
  signal?: AbortSignal,
  timeoutMs?: number
): Promise<{ healthy: boolean; latency?: number; error?: string }> {
  const startTime = Date.now()
  const healthTimeout = timeoutMs ?? service.timeout
  try {
    const controller = new AbortController()
    const t = setTimeout(() => controller.abort(), healthTimeout)

    if (signal) {
      signal.addEventListener('abort', () => controller.abort())
    }

    const response = await fetch(`${service.url}${service.healthEndpoint}`, {
      signal: controller.signal,
      headers: {
        'User-Agent': 'NextEleven-HealthCheck/1.0',
      },
    })

    clearTimeout(t)
    const latency = Date.now() - startTime

    if (response.ok) {
      return { healthy: true, latency }
    } else {
      return { healthy: false, latency, error: `HTTP ${response.status}` }
    }
  } catch (error) {
    const latency = Date.now() - startTime
    return {
      healthy: false,
      latency,
      error: error instanceof Error ? error.message : 'Connection failed',
    }
  }
}

// Retry wrapper for service calls
export async function withRetry<T>(
  fn: () => Promise<T>,
  retries: number = 3,
  delay: number = 1000,
  backoff: number = 2
): Promise<T> {
  let lastError: Error | unknown

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn()
    } catch (error) {
      lastError = error

      if (attempt < retries) {
        const waitTime = delay * Math.pow(backoff, attempt)
        await new Promise(resolve => setTimeout(resolve, waitTime))
        continue
      }

      // Last attempt failed, throw the error
      throw error
    }
  }

  // This should never be reached, but TypeScript needs it for type safety
  throw lastError || new Error('Retry failed: unknown error')
}

// Get service URL helper
export function getServiceUrl(service: keyof AppConfig['services']): string {
  return config.services[service].url
}

/**
 * xAI TTS via Grok Voice Agent API (WebSocket)
 * Current as of March 2026: https://docs.x.ai/developers/model-capabilities/audio/voice-agent
 * Voices: Eve, Ara, Rex, Sal, Leo
 */
import WebSocket from 'ws'

const XAI_REALTIME_URL = 'wss://api.x.ai/v1/realtime'
const SAMPLE_RATE = 24000

export const XAI_VOICES = [
  { voice_id: 'Eve', name: 'Eve', description: 'Energetic, upbeat', gender: 'female', source: 'xai', category: 'xai' },
  { voice_id: 'Ara', name: 'Ara', description: 'Warm, friendly', gender: 'female', source: 'xai', category: 'xai' },
  { voice_id: 'Rex', name: 'Rex', description: 'Confident, clear', gender: 'male', source: 'xai', category: 'xai' },
  { voice_id: 'Sal', name: 'Sal', description: 'Smooth, balanced', gender: 'neutral', source: 'xai', category: 'xai' },
  { voice_id: 'Leo', name: 'Leo', description: 'Authoritative, strong', gender: 'male', source: 'xai', category: 'xai' },
] as const

const VALID_VOICE_IDS = new Set(XAI_VOICES.map((v) => v.voice_id))

export function getXaiVoices() {
  return [...XAI_VOICES]
}

export function isValidXaiVoice(voiceId: string): boolean {
  return VALID_VOICE_IDS.has(voiceId as (typeof XAI_VOICES)[number]['voice_id'])
}

/**
 * Generate speech via xAI Voice Agent WebSocket.
 * Returns PCM16 mono at SAMPLE_RATE; caller can wrap in WAV if needed.
 */
export function synthesizeXai(params: {
  text: string
  voiceId: string
  apiKey: string
}): Promise<Buffer> {
  const { text, voiceId, apiKey } = params
  if (!text?.trim()) return Promise.reject(new Error('text is required'))
  if (!isValidXaiVoice(voiceId)) return Promise.reject(new Error(`Invalid xAI voice: ${voiceId}`))
  if (!apiKey) return Promise.reject(new Error('XAI_API_KEY is required'))

  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = []
    const timeout = setTimeout(() => {
      try {
        ws.close()
      } catch {
        /* ignore */
      }
      reject(new Error('xAI TTS timeout'))
    }, 60000)

    const ws = new WebSocket(XAI_REALTIME_URL, {
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
    })

    ws.on('error', (err: Error) => {
      clearTimeout(timeout)
      reject(err)
    })

    ws.on('close', () => {
      clearTimeout(timeout)
      if (chunks.length > 0) {
        resolve(Buffer.concat(chunks))
      } else {
        reject(new Error('xAI returned no audio — check voice and API key'))
      }
    })

    let finished = false
    ws.on('open', () => {
      // Configure session for pure TTS
      ws.send(
        JSON.stringify({
          type: 'session.update',
          session: {
            voice: voiceId,
            instructions: 'You are a text-to-speech engine. Only produce audio output.',
            turn_detection: null,
            modalities: ['audio'],
          },
        })
      )
      // Send text as an ASSISTANT message — this tells the model the assistant
      // has already decided to say these words, so it renders audio for them
      // verbatim without interpreting or responding to the content.
      ws.send(
        JSON.stringify({
          type: 'conversation.item.create',
          item: {
            type: 'message',
            role: 'assistant',
            content: [{ type: 'text', text: text.trim() }],
          },
        })
      )
      // Request audio rendering of the assistant message
      ws.send(
        JSON.stringify({
          type: 'response.create',
          response: {
            modalities: ['audio'],
          },
        })
      )
    })

    ws.on('message', (data: Buffer | string) => {
      try {
        const event = JSON.parse(data.toString())
        if (event.type === 'response.output_audio.delta' && event.delta) {
          chunks.push(Buffer.from(event.delta, 'base64'))
        } else if (event.type === 'response.output_audio.done' || event.type === 'response.done') {
          finished = true
          clearTimeout(timeout)
          ws.close()
        } else if (event.type === 'error') {
          clearTimeout(timeout)
          ws.close()
          reject(new Error(event.message || 'xAI API error'))
        }
      } catch {
        // ignore
      }
    })
  })
}

export function pcmToWav(pcm: Buffer, sampleRate: number = SAMPLE_RATE): Buffer {
  const numChannels = 1
  const bitsPerSample = 16
  const byteRate = sampleRate * numChannels * (bitsPerSample / 8)
  const dataSize = pcm.length
  const header = Buffer.alloc(44)
  header.write('RIFF', 0)
  header.writeUInt32LE(36 + dataSize, 4)
  header.write('WAVE', 8)
  header.write('fmt ', 12)
  header.writeUInt32LE(16, 16)
  header.writeUInt16LE(1, 20)
  header.writeUInt16LE(numChannels, 22)
  header.writeUInt32LE(sampleRate, 24)
  header.writeUInt32LE(byteRate, 28)
  header.writeUInt16LE(numChannels * (bitsPerSample / 8), 32)
  header.writeUInt16LE(bitsPerSample, 34)
  header.write('data', 36)
  header.writeUInt32LE(dataSize, 40)
  return Buffer.concat([header, pcm])
}
